/**
 * Tree Grid Extractor
 *
 * Extracts individual trees from grid/row arrangements generated by Gemini.
 * Handles both single rows and multi-row grids by detecting connected components.
 *
 * Usage: node scripts/extract-tree-grid.cjs <input-image> <category>
 */

const { createCanvas, loadImage } = require('canvas');
const fs = require('fs');
const path = require('path');

const OUTPUT_DIR = 'static/images/trees/curated';

async function extractTrees(inputPath, category) {
  console.log(`\nExtracting ${category} trees from: ${inputPath}`);

  const img = await loadImage(inputPath);
  const width = img.width;
  const height = img.height;

  console.log(`Image size: ${width}x${height}`);

  const canvas = createCanvas(width, height);
  const ctx = canvas.getContext('2d');
  ctx.drawImage(img, 0, 0);
  const imageData = ctx.getImageData(0, 0, width, height);
  const pixels = imageData.data;

  // Track visited pixels for flood fill
  const visited = new Array(width * height).fill(false);

  function getPixel(x, y) {
    if (x < 0 || x >= width || y < 0 || y >= height) return { r: 255, g: 255, b: 255 };
    const idx = (y * width + x) * 4;
    return { r: pixels[idx], g: pixels[idx + 1], b: pixels[idx + 2] };
  }

  function isBlack(x, y) {
    const p = getPixel(x, y);
    return p.r < 100 && p.g < 100 && p.b < 100;
  }

  function isVisited(x, y) {
    return visited[y * width + x];
  }

  function setVisited(x, y) {
    visited[y * width + x] = true;
  }

  // Flood fill to find connected component bounds
  function floodFillBounds(startX, startY) {
    const stack = [[startX, startY]];
    let minX = startX, maxX = startX, minY = startY, maxY = startY;
    let pixelCount = 0;

    while (stack.length > 0) {
      const [x, y] = stack.pop();

      if (x < 0 || x >= width || y < 0 || y >= height) continue;
      if (isVisited(x, y)) continue;
      if (!isBlack(x, y)) continue;

      setVisited(x, y);
      pixelCount++;

      if (x < minX) minX = x;
      if (x > maxX) maxX = x;
      if (y < minY) minY = y;
      if (y > maxY) maxY = y;

      // Check 8-connected neighbors
      stack.push([x + 1, y]);
      stack.push([x - 1, y]);
      stack.push([x, y + 1]);
      stack.push([x, y - 1]);
      stack.push([x + 1, y + 1]);
      stack.push([x - 1, y - 1]);
      stack.push([x + 1, y - 1]);
      stack.push([x - 1, y + 1]);
    }

    return { minX, maxX, minY, maxY, pixelCount };
  }

  // Find all connected components (potential trees)
  console.log('Finding connected components...');
  const components = [];

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      if (!isVisited(x, y) && isBlack(x, y)) {
        const bounds = floodFillBounds(x, y);
        const w = bounds.maxX - bounds.minX + 1;
        const h = bounds.maxY - bounds.minY + 1;

        // Filter out tiny components (noise) and text labels
        // Trees should be substantial - at least 50x50 pixels and have significant area
        if (w > 50 && h > 50 && bounds.pixelCount > 1000) {
          components.push({
            ...bounds,
            width: w,
            height: h,
            centerX: (bounds.minX + bounds.maxX) / 2,
            centerY: (bounds.minY + bounds.maxY) / 2,
          });
        }
      }
    }
  }

  console.log(`Found ${components.length} potential trees`);

  // Sort by position (top-left to bottom-right, row by row)
  components.sort((a, b) => {
    // Group by rows (trees within 100px vertical are same row)
    const rowA = Math.floor(a.centerY / 100);
    const rowB = Math.floor(b.centerY / 100);
    if (rowA !== rowB) return rowA - rowB;
    return a.centerX - b.centerX;
  });

  // Get existing file count for this category
  if (!fs.existsSync(OUTPUT_DIR)) {
    fs.mkdirSync(OUTPUT_DIR, { recursive: true });
  }

  const existingFiles = fs.readdirSync(OUTPUT_DIR).filter(f => f.startsWith(`${category}_`));
  const existingNumbers = existingFiles.map(f => {
    const match = f.match(new RegExp(`${category}_(\\d+)\\.png`));
    return match ? parseInt(match[1]) : 0;
  });
  let nextNum = existingNumbers.length > 0 ? Math.max(...existingNumbers) + 1 : 1;

  // Extract and save each tree
  const extracted = [];

  for (let i = 0; i < components.length; i++) {
    const comp = components[i];

    // Add padding
    const padding = 15;
    const x1 = Math.max(0, comp.minX - padding);
    const y1 = Math.max(0, comp.minY - padding);
    const x2 = Math.min(width - 1, comp.maxX + padding);
    const y2 = Math.min(height - 1, comp.maxY + padding);
    const w = x2 - x1 + 1;
    const h = y2 - y1 + 1;

    // Validate aspect ratio (trees are typically taller than wide or roughly square)
    const aspectRatio = h / w;
    if (aspectRatio < 0.3) {
      console.log(`  Skipping component ${i + 1}: unusual aspect ratio ${aspectRatio.toFixed(2)}`);
      continue;
    }

    // Create tree canvas
    const treeCanvas = createCanvas(w, h);
    const treeCtx = treeCanvas.getContext('2d');

    // Fill with white
    treeCtx.fillStyle = 'white';
    treeCtx.fillRect(0, 0, w, h);

    // Copy tree region
    const sourceData = ctx.getImageData(x1, y1, w, h);
    treeCtx.putImageData(sourceData, 0, 0);

    // Save
    const filename = `${category}_${String(nextNum).padStart(2, '0')}.png`;
    const outputPath = path.join(OUTPUT_DIR, filename);
    const buffer = treeCanvas.toBuffer('image/png');
    fs.writeFileSync(outputPath, buffer);

    console.log(`  Saved: ${filename} (${w}x${h})`);
    extracted.push(filename);
    nextNum++;
  }

  console.log(`\n✓ Extracted ${extracted.length} trees`);
  return extracted;
}

// CLI
const args = process.argv.slice(2);

if (args.length < 2) {
  console.log(`
Usage: node scripts/extract-tree-grid.cjs <input-image> <category>

Categories: dead, maple, willow, oak, pine, fir, spruce, poplar
`);
  process.exit(1);
}

const [inputPath, category] = args;

if (!fs.existsSync(inputPath)) {
  console.error(`File not found: ${inputPath}`);
  process.exit(1);
}

extractTrees(inputPath, category)
  .then(() => console.log('Done!'))
  .catch(err => {
    console.error('Error:', err);
    process.exit(1);
  });
